def most_frequent_char(s):
    counts = {}
    first_seen = {}
    for idx, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        if ch not in first_seen:
            first_seen[ch] = idx
    best_ch = s[0]
    best_count = -1
    for ch, count in counts.items():
        if count > best_count:
            best_count = count
            best_ch = ch
        elif count == best_count and first_seen[ch] < first_seen[best_ch]:
            best_ch = ch
    return best_ch
```

